import { useState } from 'react';
import { type Project, type Task, measure, addTask, toggleTask, editTask, removeTask } from './task-tree.js';
import { ProgressBar } from './progress-bar.js';
import { TaskItem, type TaskActions } from './task-item.js';
import { TaskForm } from './task-form.js';
import styles from './trellis-app.module.css';

/**
 * Detail view for one project: overall progress, top-level task breakdown and the task tree.
 * @param props.project - project to show
 * @param props.onTasks - applies a transformation to the project's task tree
 * @param props.onDelete - deletes the project
 */
export function ProjectView({
  project,
  onTasks,
  onDelete,
}: {
  project: Project;
  onTasks: (fn: (t: Task[]) => Task[]) => void;
  onDelete: () => void;
}) {
  const [adding, setAdding] = useState(false);
  const p = measure(project.tasks);
  const color = project.color;

  const actions: TaskActions = {
    onToggle: (id) => onTasks((t) => toggleTask(t, id)),
    onAdd: (parentId, v) => onTasks((t) => addTask(t, parentId, v)),
    onEdit: (id, v) => onTasks((t) => editTask(t, id, v)),
    onRemove: (id) => onTasks((t) => removeTask(t, id)),
  };

  return (
    <section className={styles.project}>
      <header className={styles.projectHeader}>
        <div className={styles.projectTitleRow}>
          <span className={styles.dot} style={{ background: color }} />
          <h1 className={styles.projectTitle}>{project.name}</h1>
          <span className={styles.bigPercent} style={{ color: p.percent === 100 ? 'var(--success)' : color }}>
            {p.percent}%
          </span>
        </div>
        {project.description ? <p className={styles.projectDesc}>{project.description}</p> : null}
        <ProgressBar percent={p.percent} color={color} size="lg" />
        <div className={styles.projectStats}>
          <span>{p.done} of {p.total} tasks complete</span>
          <button
            className={styles.dangerLink}
            onClick={() => window.confirm(`Delete project "${project.name}"?`) && onDelete()}
          >
            Delete project
          </button>
        </div>
      </header>

      {project.tasks.length ? (
        <div className={styles.breakdown}>
          {project.tasks.map((t) => {
            const tp = measure(t.subtasks?.length ? t.subtasks : [t]);
            return (
              <div key={t.id} className={styles.breakdownCard}>
                <span className={styles.breakdownName}>{t.title}</span>
                <span className={styles.breakdownPct}>{tp.percent}%</span>
                <ProgressBar percent={tp.percent} color={color} />
              </div>
            );
          })}
        </div>
      ) : null}

      <div className={styles.tasksPanel}>
        <div className={styles.panelHead}>
          <h2>Tasks</h2>
          {!adding ? (
            <button className={styles.primaryBtn} onClick={() => setAdding(true)}>+ New task</button>
          ) : null}
        </div>
        {adding ? (
          <TaskForm
            placeholder="e.g. Gun system"
            onCancel={() => setAdding(false)}
            onSubmit={(v) => onTasks((t) => addTask(t, null, v))}
          />
        ) : null}
        {project.tasks.length ? (
          <ul className={styles.taskList}>
            {project.tasks.map((t) => (
              <TaskItem key={t.id} task={t} depth={0} color={color} actions={actions} />
            ))}
          </ul>
        ) : !adding ? (
          <p className={styles.empty}>No tasks yet. Add your first one — then break it into sub-tasks with ＋.</p>
        ) : null}
      </div>
    </section>
  );
}
